    dataClient = new AsyncDataClient(null, null, null) {
      @Override
      public void querySingleSeriesByTimestamp(SingleSeriesQueryRequest request,
          AsyncMethodCallback<Long> resultHandler) {
        resultHandler.onComplete(1L);
