        loadUnhandledXmlObject();

        samlToken = new Saml20TokenImpl(ASSERTION_MCK, PROVIDER_ID);

        samlToken.holderOfKeyBytes = EXPECTED_HOLDER_OF_KEY_BYTES;
    }

